     8→object CatalogMergeStrategy : MergeStrategy<Catalog> {
     9→    private val logger by logger()
    10→
    11→    override fun merge(documents: List<ChangedData<Catalog>>): List<ChangedData<Catalog>> {
    12→        return documents
    13→            .groupBy { it.id } // 같은 문서로 그룹핑
    14→            .map { (_, group) ->
    15→                if (group.size == 1) {
    16→                    group.first()
    17→                } else {
    18→                    var isChangedCategory = false
    19→                    var isChangedBrand = false
    20→                    var isChangedManufacturer = false
    21→
    22→                    group.sortedBy { it.offset } // offset 기준으로 정렬
    23→                        .fold(null as ChangedData<Catalog>?) { acc, current ->
    24→                            when (current.op) {
    25→                                Operation.CREATE -> {
    26→                                    isChangedCategory = true
    27→                                    isChangedBrand = true
    28→                                    isChangedManufacturer = true
    29→                                }
    30→                                Operation.UPDATE -> {
    31→                                    // Note. update 메시지의 before가 null인 경우 존재
    32→                                    if (current.beforeData != null && current.afterData != null) {
    33→                                        current.beforeData.`id$1`
    34→                                        current.beforeData.categoryId
    35→                                        if (current.beforeData.categoryId != current.afterData.categoryId) isChangedCategory = true
    36→                                        if (current.beforeData.brandId != current.afterData.brandId) isChangedBrand = true
    37→                                        if (current.beforeData.manufacturerId != current.afterData.manufacturerId) isChangedManufacturer = true
    38→                                    }
    39→                                }
    40→                                Operation.DELETE -> {
    41→                                    isChangedCategory = false
    42→                                    isChangedBrand = false
    43→                                    isChangedManufacturer = false
    44→                                }
    45→                            }
    46→
    47→                            merge(acc, current)
    48→                                .also {
    49→                                    if (it == null) {
    50→                                        // Note. merge result가 null인 경우, acc는 not null이 보장됨
    51→                                        logger.warn { "[CatalogMergeStrategy] Unexpected operation. "  + diffLog(acc!!, current) }
    52→                                    }
    53→                            }
    54→                        }
    55→                        .apply {
    56→                            this?.shouldFetchCategory = isChangedCategory
    57→                            this?.shouldFetchBrand = isChangedBrand
    58→                            this?.shouldFetchManufacturer = isChangedManufacturer
    59→                        }
    60→                }
    61→            }
    62→            .filterNotNull()
    63→    }
    64→}

