    38→                        emptyMap()
    39→                    } else {
    40→                        brandService.getBrands(dependencyId.brandIds).associateBy { it.id }
    41→                    }
    42→                }
    43→            val manufacturersDeferred =
    44→                async {
    45→                    if (dependencyId.manufacturerIds.isEmpty()) {
    46→                        emptyMap()
    47→                    } else {
    48→                        manufacturerService.getManufacturers(dependencyId.manufacturerIds).associateBy { it.id }
